using System;using System.Collections.Generic;using System.Linq;using Exoduser.UnityPort.Core.Skills;
namespace Exoduser.UnityPort.Core {
 public sealed class ForgeOrb {public string Id,Role,Badge;public bool Material,Dim,Sealed,Glow,On,Host;public int Priority,Level;public double Strength,X,Y,Size,LabelWidth,LabelGap;}
 public sealed class ForgeEdge {public string A,B;public bool Core;public double Strength;}
 public sealed class SkillForgePresentation {
  public readonly List<ForgeOrb> Orbs=new List<ForgeOrb>();public readonly List<ForgeEdge> Edges=new List<ForgeEdge>();public double Size,MaximumSize;public bool Compact;
  public static SkillForgePresentation Build(FullSkillLedger ledger,int slot,SkillForgeModel model){var output=new SkillForgePresentation();var items=new Dictionary<string,ForgeOrb>();string current=ledger.Equipped(slot);if(model.Host!=null)foreach(var c in model.Candidates){if(items.ContainsKey(c.Id))continue;var it=new ForgeOrb{Id=c.Id,Material=true,Role="none",Badge=""};if(c.Hidden&&!c.Learned){it.Sealed=true;it.Priority=5;it.Strength=.12;}else if(c.DemoLocked){it.Dim=true;it.Badge="정식판";it.Priority=4;it.Strength=.14;}else if(!c.Learned){it.Dim=true;it.Badge="습득 필요";it.Priority=3;it.Strength=.14;}else if(c.Allowed&&c.Completes){it.Glow=true;it.Strength=1;}else if(c.Allowed&&!c.Later){it.Badge="추가 재료";it.Priority=1;it.Strength=.45;}else{it.Dim=true;it.Badge="다음 단계";it.Priority=2;it.Strength=.14;}it.Role=c.Allowed&&c.Learned&&!c.DemoLocked?"mat":"none";items[c.Id]=it;output.Orbs.Add(it);}
   foreach(string id in SkillForgeModel.Eligible(ledger,slot)){if(!items.TryGetValue(id,out var it)){it=new ForgeOrb{Id=id,Role="equip",Badge="",Priority=id==current?10:ledger.Level(id)>0?11:12,Dim=!ledger.CanEquip(slot,id)};items[id]=it;output.Orbs.Add(it);}else if(it.Role=="none"&&ledger.CanEquip(slot,id)){it.Role="equip";it.Dim=false;}if(id==current)it.On=true;}foreach(var it in output.Orbs){it.Host=SkillForgeModel.IsHost(it.Id);it.Level=ledger.Level(it.Id);if(it.Material)output.Edges.Add(new ForgeEdge{A=it.Id,B="core",Core=true,Strength=it.Strength});}var seen=new HashSet<string>();foreach(var f in FullSkillLedger.Fusions){string host=SkillForgeModel.FusionHost(f.Key);if(host==model.Host)continue;foreach(string id in f.Members){if(id==host||id==model.Host)continue;string key=String.CompareOrdinal(host,id)<0?host+"|"+id:id+"|"+host;if(!seen.Add(key))continue;if(items.ContainsKey(host)&&items.ContainsKey(id))output.Edges.Add(new ForgeEdge{A=host,B=id,Strength=.3});}}return output;
  }
  public void Layout(SkillForgeGeometry g,IEnumerable<ForgeReserved> reserved){MaximumSize=Math.Max(34,Math.Min(58,Math.Min(g.H*.088,g.W*.052)));if(Orbs.Count==0){Size=MaximumSize;return;}var slots=g.Fit(Orbs.Count,reserved,out double size,out bool compact);Size=size;Compact=compact;var parent=Orbs.ToDictionary(it=>it.Id,it=>it.Id);Func<string,string> find=x=>{while(parent[x]!=x)x=parent[x];return x;};foreach(var edge in Edges)if(!edge.Core){string a=find(edge.A),b=find(edge.B);if(a!=b)parent[a]=b;}var groups=new Dictionary<string,List<ForgeOrb>>();foreach(var it in Orbs){string key=find(it.Id);if(!groups.TryGetValue(key,out var gr)){gr=new List<ForgeOrb>();groups[key]=gr;}gr.Add(it);}var sorted=groups.Values.Select(gr=>gr.OrderBy(it=>it.Priority).ThenByDescending(it=>it.Level).ToList()).OrderBy(gr=>gr[0].Priority).ThenByDescending(gr=>gr.Count);ForgePoint last=null;int nL=0,nR=0;
   foreach(var group in sorted){bool left=nL<=nR;var side=left?slots.L:slots.R;var other=left?slots.R:slots.L;if(side.Count+slots.M.Count<group.Count&&other.Count>=group.Count){var tmp=side;side=other;other=tmp;}var near=new List<ForgePoint>();foreach(var it in group){var p=Pick(side,near)??Pick(slots.M,near)??Pick(other,near);if(p==null){if(last==null)last=new ForgePoint{x=g.cx-g.discR-40,y=40};p=new ForgePoint{x=last.x,y=last.y+14};}last=p;near.Add(p);it.X=p.x;it.Y=p.y;it.Size=size;it.LabelWidth=slots.Lw;it.LabelGap=slots.lg;if(p.x<g.cx)nL++;else nR++;}}
  }
  static ForgePoint Pick(List<ForgePoint> q,List<ForgePoint> near){if(q.Count==0)return null;int best=0;if(near.Count>0){double score=1e9;for(int i=0;i<q.Count;i++){double d=near.Min(n=>Math.Sqrt((q[i].x-n.x)*(q[i].x-n.x)+(q[i].y-n.y)*(q[i].y-n.y)));double s=d+q[i].score*.12;if(s<score){score=s;best=i;}}}var p=q[best];q.RemoveAt(best);return p;}
 }
}
